package org.bukkit; public class Location implements Cloneable {public World world; public double x,y,z; public Location(World w,double x,double y,double z){world=w;this.x=x;this.y=y;this.z=z;} public World getWorld(){return world;} public int getBlockX(){return (int)Math.floor(x);} public int getBlockZ(){return (int)Math.floor(z);} public Location clone(){return new Location(world,x,y,z);} public Location add(double x,double y,double z){this.x+=x;this.y+=y;this.z+=z;return this;} }
